firefox.policiesFiles.description:
JSON files containing policies to be injected into the wrapped package.

To inject preferences, code like this can be used:
```json
{
  "policies": {
    "Preferences": {
      "YOUR_PREFERENCES": "here"
    }
  }
}
```

See the Firefox documentation:
https://support.mozilla.org/en-US/kb/customizing-firefox-using-policiesjson

Disjoint with the `policies` option.

example.text:
{
  c = "git commit";
  git = [
    {
      m = "merge";
    }
    {
      rbi = {
        expansion = "rebase -i HEAD~%";
        setCursor = true;
      };
    }
  ];
  s = "git status";
}

{
  branch_find = { };
  commit_amend = {
    char = "Char('A')";
    mod = "SHIFT";
  };
  move_left = {
    char = "Char('h')";
  };
}

{
  G = {
    command = "| grep";
    global = true;
  };
  ls = "ls --color";
}

{
  appendhistory = true;
  autocd = false;
  beep = false;
  sharehistory = true;
}
